/** What `syncProjects` receives: the cursor Ajour kept from the last sync,
absent on the first, and what started the sync. `manual` is a sync the user
asked for, such as Sync now: a plugin that answers from a cache should read
the source. `auto` is the scheduler's. Older Ajour versions send no trigger. */
export type ProjectSourceSyncRequest = {
  trigger?: "manual" | "auto" | undefined;
  cursor?: string | undefined;
};

/** What `syncProjects` answers: the snapshot and the next cursor, or that nothing changed. */
export type ProjectSourceSyncResult =
  | { unchanged: true }
  | {
      snapshot: {
        source: { label: string; url?: string | undefined };
        projects: {
          code: string;
          name: string;
          remoteId: string;
          tasks: {
            name: string;
            remoteId: string;
            assigned: boolean;
            closed: boolean;
            billable?: boolean | undefined;
            group?: string | undefined;
            estimateHours?: number | undefined;
            myHours?: number | undefined;
            workedHours?: number | undefined;
          }[];
          complete: boolean;
          url?: string | undefined;
          client?: string | undefined;
          startsOn?: string | undefined;
          endsOn?: string | undefined;
          budget?:
            | {
                unit: "hours" | "money";
                consumed: number;
                status?: "unknown" | "ok" | "warning" | "over" | undefined;
                since?: string | undefined;
                total?: number | undefined;
                remaining?: number | undefined;
              }
            | undefined;
        }[];
        asOf: string;
        me?:
          | {
              hoursAvailable: boolean;
              hoursNote?: string | undefined;
              hoursSince?: string | undefined;
            }
          | undefined;
      };
      cursor?: string | undefined;
    };

/** The user's projects, tasks and budgets as the source knows them, as of `asOf`. */
