/** What `syncTimeEntries` receives: the window to list, as local dates in the
user's time zone, at most 20 changes to apply first, in order, and the
cursor of your last answer, when Ajour holds one. An older Ajour sends
no cursor. */
export type TimeSyncRequest = {
  changes: (
    | {
        values: {
          running: boolean;
          localDate: string;
          minutes: number;
          projectRemoteId: string;
          taskName: string;
          countingSince?: string | undefined;
          taskRemoteId?: string | undefined;
        };
        kind: "upsert";
        syncKey: string;
        remoteId?: string | undefined;
        agreed?:
          | {
              running: boolean;
              localDate: string;
              minutes: number;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
            }
          | undefined;
      }
    | {
        kind: "delete";
        syncKey: string;
        remoteId?: string | undefined;
        agreed?:
          | {
              running: boolean;
              localDate: string;
              minutes: number;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
            }
          | undefined;
      }
  )[];
  from: string;
  timeZone: string;
  to: string;
  cursor?: string | undefined;
};

/** One change: an entry to create or update, or one to delete. Send its
`syncKey` as your client reference, so a retry never duplicates. `agreed`
holds the values both sides last agreed on, when there are some. */
export type TimeSyncChange =
  | {
      values: {
        running: boolean;
        localDate: string;
        minutes: number;
        projectRemoteId: string;
        taskName: string;
        countingSince?: string | undefined;
        taskRemoteId?: string | undefined;
      };
      kind: "upsert";
      syncKey: string;
      remoteId?: string | undefined;
      agreed?:
        | {
            running: boolean;
            localDate: string;
            minutes: number;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
          }
        | undefined;
    }
  | {
      kind: "delete";
      syncKey: string;
      remoteId?: string | undefined;
      agreed?:
        | {
            running: boolean;
            localDate: string;
            minutes: number;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
          }
        | undefined;
    };

/** An entry's values: its day, whole minutes, whether it runs and since when
its count started, its project and its task. Never a note. */
export type TimeSyncEntryValues = {
  running: boolean;
  localDate: string;
  minutes: number;
  projectRemoteId: string;
  taskName: string;
  countingSince?: string | undefined;
  taskRemoteId?: string | undefined;
};

/** What `syncTimeEntries` answers: the full answer, or unchanged to a check round. */
export type TimeSyncAnswer =
  | {
      entries: {
        running: boolean;
        updatedAt: string;
        remoteId: string;
        localDate: string;
        minutes: number;
        projectRemoteId: string;
        taskName: string;
        countingSince?: string | undefined;
        taskRemoteId?: string | undefined;
        clientRef?: string | undefined;
      }[];
      results: (
        | {
            status: "synced";
            syncKey: string;
            entry?:
              | {
                  running: boolean;
                  updatedAt: string;
                  remoteId: string;
                  localDate: string;
                  minutes: number;
                  projectRemoteId: string;
                  taskName: string;
                  countingSince?: string | undefined;
                  taskRemoteId?: string | undefined;
                  clientRef?: string | undefined;
                }
              | undefined;
          }
        | { message: string; status: "refused"; syncKey: string }
        | { message: string; status: "failed"; syncKey: string }
      )[];
      cursor?: string | undefined;
    }
  | { cursor: string; unchanged: true };

/** The full answer: one result per change, the remote entries in the window,
and, when your system keeps a change marker, the cursor Ajour sends back
in its next check round. Without a cursor, every round lists. */
export type TimeSyncResult = {
  entries: {
    running: boolean;
    updatedAt: string;
    remoteId: string;
    localDate: string;
    minutes: number;
    projectRemoteId: string;
    taskName: string;
    countingSince?: string | undefined;
    taskRemoteId?: string | undefined;
    clientRef?: string | undefined;
  }[];
  results: (
    | {
        status: "synced";
        syncKey: string;
        entry?:
          | {
              running: boolean;
              updatedAt: string;
              remoteId: string;
              localDate: string;
              minutes: number;
              projectRemoteId: string;
              taskName: string;
              countingSince?: string | undefined;
              taskRemoteId?: string | undefined;
              clientRef?: string | undefined;
            }
          | undefined;
      }
    | { message: string; status: "refused"; syncKey: string }
    | { message: string; status: "failed"; syncKey: string }
  )[];
  cursor?: string | undefined;
};

/** The answer to a check round, a request with a cursor and no changes, when
nothing changed in your system since that cursor: the cursor for the next
check, without listing. Ajour refuses it to any other request. */
export type TimeSyncUnchangedResult = { cursor: string; unchanged: true };

/** How one change went: `synced` with the entry as stored (none for a
delete), `refused` for good with a sentence the user reads, or `failed`
with a sentence, to retry next round. */
export type TimeSyncChangeResult =
  | {
      status: "synced";
      syncKey: string;
      entry?:
        | {
            running: boolean;
            updatedAt: string;
            remoteId: string;
            localDate: string;
            minutes: number;
            projectRemoteId: string;
            taskName: string;
            countingSince?: string | undefined;
            taskRemoteId?: string | undefined;
            clientRef?: string | undefined;
          }
        | undefined;
    }
  | { message: string; status: "refused"; syncKey: string }
  | { message: string; status: "failed"; syncKey: string };

/** An entry as your system stores it, with `clientRef` when Ajour created it. */
export type TimeSyncRemoteEntry = {
  running: boolean;
  updatedAt: string;
  remoteId: string;
  localDate: string;
  minutes: number;
  projectRemoteId: string;
  taskName: string;
  countingSince?: string | undefined;
  taskRemoteId?: string | undefined;
  clientRef?: string | undefined;
};

